SELECT sys_id AS "sysId", grp_cd AS "grpCd", upr_com_cd AS "uprComCd", com_cd AS "comCd", cd_nm AS "cdNm", cd_expl AS "cdExpl", sort_ord AS "sortOrd", use_yn AS "useYn"
FROM TN_COM_C002 WHERE sys_id = #{sysId} AND grp_cd = #{grpCd} AND upr_com_cd = #{uprComCd}
ORDER BY sort_ord ASC, com_cd ASC
